export function elevenlabs(options) {
    return {
        baseUrl: 'https://api.elevenlabs.io/v1',
        headers: {
            'xi-api-key': options.apiKey,
            'Content-Type': 'application/json',
        },
        timeout: 3 * 60 * 1000,
        retry: {
            maxAttempts: 2,
            backoff: 'exponential',
            delay: 2000,
            statusCodes: [408, 429, 500, 502, 503, 504],
        }
    };
}
export const elevenlabsVoices = (options) => ({
    ...elevenlabs(options),
    baseUrl: 'https://api.elevenlabs.io/v1/voices',
});
