export function gitlab(options) {
    return {
        baseUrl: `${options.baseUrl || 'https://gitlab.com'}/api/v4`,
        headers: {
            'PRIVATE-TOKEN': options.token,
            'Content-Type': 'application/json',
        },
        timeout: 30 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504]
        }
    };
}
