export function pinecone(options) {
    let baseUrl;
    if (options.host) {
        baseUrl = `https://${options.host}`;
    }
    else if (options.environment) {
        baseUrl = `https://controller.${options.environment}.pinecone.io`;
    }
    else {
        baseUrl = 'https://api.pinecone.io';
    }
    return {
        baseUrl,
        headers: {
            'Api-Key': options.apiKey,
            'Content-Type': 'application/json',
        },
        timeout: 5 * 60 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504],
        }
    };
}
export function pineconeControl(options) {
    return {
        baseUrl: 'https://api.pinecone.io',
        headers: {
            'Api-Key': options.apiKey,
            'Content-Type': 'application/json',
        },
        timeout: 60 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504],
        }
    };
}
