const VERSION = '__INJECT_VERSION__';
let _version = null;
export async function getVersion() {
    if (_version)
        return _version;
    if (VERSION !== '__INJECT_VERSION__') {
        _version = VERSION;
        return _version;
    }
    try {
        const pkg = await import('../package.json', { with: { type: 'json' } });
        _version = pkg.default?.version || '0.0.0-dev';
    }
    catch {
        _version = '0.0.0-dev';
    }
    return _version;
}
export function getVersionSync() {
    if (_version)
        return _version;
    if (VERSION !== '__INJECT_VERSION__')
        return VERSION;
    return '0.0.0-dev';
}
export async function getVersionInfo() {
    const version = await getVersion();
    return {
        version,
        name: 'recker',
        nodeVersion: process.version,
        platform: process.platform,
        arch: process.arch,
    };
}
export async function formatVersionInfo(verbose = false) {
    const info = await getVersionInfo();
    if (verbose) {
        return [
            `recker/${info.version}`,
            `node/${info.nodeVersion.replace('v', '')}`,
            `${info.platform}/${info.arch}`,
        ].join(' ');
    }
    return info.version;
}
