export function mistral(options) {
    const _aiConfig = {
        provider: 'mistral',
        apiKey: options.apiKey,
        model: options.model ?? 'mistral-large-3',
        memory: { maxPairs: 12 },
    };
    return {
        baseUrl: 'https://api.mistral.ai/v1',
        headers: {
            'Authorization': `Bearer ${options.apiKey}`,
        },
        timeout: 5 * 60 * 1000,
        retry: {
            maxAttempts: 5,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504]
        },
        _aiConfig,
    };
}
