import { BaseAIProvider, AIError, RateLimitError, OverloadedError, AuthenticationError, } from './base.js';
export class GoogleProvider extends BaseAIProvider {
    googleConfig;
    constructor(config = {}) {
        super({ ...config, name: 'google' });
        this.googleConfig = config;
    }
    getEnvApiKey() {
        return process.env.GOOGLE_API_KEY;
    }
    getBaseUrl() {
        const version = this.googleConfig.apiVersion || 'v1beta';
        return this.config.baseUrl || `https://generativelanguage.googleapis.com/${version}`;
    }
    buildHeaders() {
        return {
            'Content-Type': 'application/json',
            ...this.config.headers,
        };
    }
    transformMessages(messages) {
        return messages
            .filter((m) => m.role !== 'system')
            .map((msg) => {
            return {
                role: msg.role === 'user' ? 'user' : 'model',
                parts: this.transformContent(msg),
            };
        });
    }
    transformContent(msg) {
        if (msg.role === 'tool') {
            return [{
                    functionResponse: {
                        name: msg.name || 'unknown_tool',
                        response: typeof msg.content === 'string' ? { content: msg.content } : { content: msg.content },
                    },
                }];
        }
        if (msg.tool_calls && msg.tool_calls.length > 0) {
            const parts = [];
            if (msg.content && typeof msg.content === 'string') {
                parts.push({ text: msg.content });
            }
            msg.tool_calls.forEach((tc) => {
                parts.push({
                    functionCall: {
                        name: tc.function.name,
                        args: JSON.parse(tc.function.arguments || '{}'),
                    },
                });
            });
            return parts;
        }
        const content = msg.content;
        if (typeof content === 'string') {
            return [{ text: content }];
        }
        if (!content)
            return [{ text: '' }];
        return content.map((part) => {
            if (part.type === 'text') {
                return { text: part.text };
            }
            if (part.type === 'image_url') {
                return { text: '[Image URL not supported directly in Gemini provider yet without base64]' };
            }
            if (part.type === 'image') {
                const base64 = Buffer.from(part.data).toString('base64');
                return {
                    inlineData: {
                        mimeType: part.mediaType,
                        data: base64,
                    },
                };
            }
            return { text: '' };
        });
    }
    transformTools(tools) {
        if (!tools || tools.length === 0)
            return undefined;
        return [{
                functionDeclarations: tools.map((t) => ({
                    name: t.function.name,
                    description: t.function.description,
                    parameters: t.function.parameters,
                })),
            }];
    }
    async chat(options) {
        const context = {
            startTime: performance.now(),
            tokenCount: 0,
        };
        const model = options.model || this.config.defaultModel || 'gemini-2.5-flash';
        const body = this.buildChatBody(options);
        const response = await this.makeRequest(`/models/${model}:generateContent`, body, options.signal);
        const data = await response.json();
        return this.parseResponse(data, context);
    }
    async stream(options) {
        const context = {
            startTime: performance.now(),
            tokenCount: 0,
        };
        const model = options.model || this.config.defaultModel || 'gemini-2.5-flash';
        const body = this.buildChatBody(options);
        const response = await this.makeRequest(`/models/${model}:streamGenerateContent?alt=sse`, body, options.signal);
        return this.parseSSEStream(response, context);
    }
    async embed(options) {
        const startTime = performance.now();
        const model = options.model || 'text-embedding-004';
        const isBatch = Array.isArray(options.input);
        const method = isBatch ? 'batchEmbedContents' : 'embedContent';
        const inputs = isBatch ? options.input : [options.input];
        const requests = inputs.map(text => ({
            model: `models/${model}`,
            content: { parts: [{ text }] }
        }));
        const body = isBatch ? { requests } : { ...requests[0] };
        const response = await this.makeRequest(`/models/${model}:${method}`, body, options.signal);
        const data = await response.json();
        let embeddings = [];
        if (isBatch) {
            embeddings = data.embeddings.map((e) => e.values);
        }
        else {
            embeddings = [data.embedding.values];
        }
        const totalTokens = 0;
        const latency = {
            ttft: performance.now() - startTime,
            tps: 0,
            total: performance.now() - startTime,
        };
        return {
            embeddings,
            usage: {
                inputTokens: totalTokens,
                outputTokens: 0,
                totalTokens,
            },
            model,
            provider: 'google',
            latency,
        };
    }
    buildChatBody(options) {
        const messages = this.transformMessages(options.messages);
        const systemMessage = options.messages.find(m => m.role === 'system');
        let systemInstruction;
        if (systemMessage) {
            systemInstruction = {
                parts: [{ text: typeof systemMessage.content === 'string' ? systemMessage.content : '' }]
            };
        }
        else if (options.systemPrompt) {
            systemInstruction = {
                parts: [{ text: options.systemPrompt }]
            };
        }
        const generationConfig = {};
        if (options.temperature !== undefined)
            generationConfig.temperature = options.temperature;
        if (options.topP !== undefined)
            generationConfig.topP = options.topP;
        if (options.maxTokens !== undefined)
            generationConfig.maxOutputTokens = options.maxTokens;
        if (options.stop)
            generationConfig.stopSequences = options.stop;
        if (options.responseFormat?.type === 'json_object') {
            generationConfig.responseMimeType = 'application/json';
        }
        const body = {
            contents: messages,
            generationConfig,
            tools: this.transformTools(options.tools),
        };
        if (systemInstruction) {
            body.systemInstruction = systemInstruction;
        }
        return body;
    }
    async makeRequest(endpoint, body, signal) {
        const key = this.getApiKey();
        const separator = endpoint.includes('?') ? '&' : '?';
        const url = `${this.getBaseUrl()}${endpoint}${separator}key=${key}`;
        const headers = this.buildHeaders();
        const response = await fetch(url, {
            method: 'POST',
            headers,
            body: JSON.stringify(body),
            signal,
        });
        if (!response.ok) {
            await this.handleError(response);
        }
        return response;
    }
    async handleError(response) {
        let errorData = {};
        try {
            errorData = await response.json();
        }
        catch {
        }
        const message = errorData.error?.message || response.statusText;
        const status = errorData.error?.code || response.status;
        switch (response.status) {
            case 400:
            case 401:
                throw new AuthenticationError('google');
            case 429:
                throw new RateLimitError('google');
            case 503:
                throw new OverloadedError('google');
        }
        throw new AIError(message, 'google', String(status), response.status, response.status >= 500);
    }
    parseResponse(data, context) {
        const candidate = data.candidates?.[0];
        const parts = candidate?.content?.parts || [];
        const content = parts
            .filter(p => p.text)
            .map(p => p.text)
            .join('');
        const toolCalls = parts
            .filter(p => p.functionCall)
            .map(p => ({
            id: 'call_' + Math.random().toString(36).slice(2),
            type: 'function',
            function: {
                name: p.functionCall.name,
                arguments: JSON.stringify(p.functionCall.args),
            }
        }));
        const usage = data.usageMetadata
            ? {
                inputTokens: data.usageMetadata.promptTokenCount,
                outputTokens: data.usageMetadata.candidatesTokenCount,
                totalTokens: data.usageMetadata.totalTokenCount,
            }
            : this.emptyUsage();
        context.tokenCount = usage.outputTokens;
        return {
            content,
            usage,
            latency: this.calculateLatency(context),
            model: 'gemini',
            provider: 'google',
            cached: false,
            finishReason: candidate?.finishReason === 'STOP' ? 'stop' : 'length',
            toolCalls: toolCalls.length > 0 ? toolCalls : undefined,
            raw: data,
        };
    }
    parseStreamEvent(chunk, context) {
        const data = JSON.parse(chunk);
        const candidate = data.candidates?.[0];
        if (!candidate)
            return null;
        if (data.usageMetadata) {
            return {
                type: 'usage',
                usage: {
                    inputTokens: data.usageMetadata.promptTokenCount,
                    outputTokens: data.usageMetadata.candidatesTokenCount,
                    totalTokens: data.usageMetadata.totalTokenCount,
                }
            };
        }
        const parts = candidate.content?.parts || [];
        const textPart = parts.find(p => p.text);
        if (textPart?.text) {
            context.tokenCount++;
            return {
                type: 'text',
                content: textPart.text,
            };
        }
        const toolPart = parts.find(p => p.functionCall);
        if (toolPart?.functionCall) {
            return {
                type: 'tool_call',
                toolCall: {
                    id: 'call_' + Math.random().toString(36).slice(2),
                    type: 'function',
                    function: {
                        name: toolPart.functionCall.name,
                        arguments: JSON.stringify(toolPart.functionCall.args),
                    }
                }
            };
        }
        if (candidate.finishReason && candidate.finishReason !== 'STOP') {
            return {
                type: 'done',
                finishReason: 'stop',
            };
        }
        return null;
    }
}
