export function square(options) {
    const baseUrl = options.sandbox
        ? 'https://connect.squareupsandbox.com/v2'
        : 'https://connect.squareup.com/v2';
    return {
        baseUrl,
        headers: {
            'Authorization': `Bearer ${options.accessToken}`,
            'Content-Type': 'application/json',
            'Square-Version': options.version || '2024-01-18',
        },
        timeout: 30 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504],
        }
    };
}
export const squarePayments = (options) => ({
    ...square(options),
    baseUrl: options.sandbox
        ? 'https://connect.squareupsandbox.com/v2/payments'
        : 'https://connect.squareup.com/v2/payments',
});
export const squareCatalog = (options) => ({
    ...square(options),
    baseUrl: options.sandbox
        ? 'https://connect.squareupsandbox.com/v2/catalog'
        : 'https://connect.squareup.com/v2/catalog',
});
export const squareSandbox = (options) => square({ ...options, sandbox: true });
