export function cohere(options) {
    const _aiConfig = {
        provider: 'cohere',
        apiKey: options.apiKey,
        model: options.model ?? 'command-a-03-2025',
        memory: { maxPairs: 12 },
    };
    return {
        baseUrl: 'https://api.cohere.ai/v1',
        headers: {
            'Authorization': `Bearer ${options.apiKey}`,
        },
        timeout: 5 * 60 * 1000,
        retry: {
            maxAttempts: 5,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504]
        },
        _aiConfig,
    };
}
