export function deepseek(options) {
    const _aiConfig = {
        provider: 'deepseek',
        apiKey: options.apiKey,
        model: options.model ?? 'deepseek-v3.2',
        memory: { maxPairs: 12 },
    };
    return {
        baseUrl: 'https://api.deepseek.com/v1',
        headers: {
            'Authorization': `Bearer ${options.apiKey}`,
        },
        timeout: 10 * 60 * 1000,
        retry: {
            maxAttempts: 5,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504]
        },
        _aiConfig,
    };
}
