export function groq(options) {
    const _aiConfig = {
        provider: 'groq',
        apiKey: options.apiKey,
        model: options.model ?? 'llama-3.3-70b-versatile',
        memory: { maxPairs: 12 },
    };
    return {
        baseUrl: 'https://api.groq.com/openai/v1',
        headers: {
            'Authorization': `Bearer ${options.apiKey}`,
        },
        timeout: 2 * 60 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 500,
            statusCodes: [408, 429, 500, 502, 503, 504]
        },
        _aiConfig,
    };
}
