const CACHE_NAME = 'recker-cache-v1';
export class ServiceWorkerCache {
    cacheName;
    cachePromise = null;
    constructor(options = {}) {
        this.cacheName = options.cacheName || CACHE_NAME;
    }
    static isSupported() {
        return typeof caches !== 'undefined';
    }
    async getCache() {
        if (!this.cachePromise) {
            if (!ServiceWorkerCache.isSupported()) {
                throw new Error('Cache API is not supported in this environment');
            }
            this.cachePromise = caches.open(this.cacheName);
        }
        return this.cachePromise;
    }
    keyToUrl(key) {
        return `https://recker-cache.local/${encodeURIComponent(key)}`;
    }
    async get(key) {
        try {
            const cache = await this.getCache();
            const url = this.keyToUrl(key);
            const response = await cache.match(url);
            if (!response) {
                return null;
            }
            const data = await response.json();
            if (data.expiresAt && Date.now() > data.expiresAt) {
                this.delete(key).catch(() => { });
                return null;
            }
            return data.entry;
        }
        catch {
            return null;
        }
    }
    async set(key, value, ttl) {
        const cache = await this.getCache();
        const url = this.keyToUrl(key);
        const item = {
            entry: value,
            expiresAt: Date.now() + ttl,
        };
        const response = new Response(JSON.stringify(item), {
            headers: {
                'Content-Type': 'application/json',
                'X-Recker-Cache': 'true',
                'X-Recker-Expires': String(item.expiresAt),
            },
        });
        await cache.put(url, response);
    }
    async delete(key) {
        const cache = await this.getCache();
        const url = this.keyToUrl(key);
        await cache.delete(url);
    }
    async clear() {
        await caches.delete(this.cacheName);
        this.cachePromise = null;
    }
    async keys() {
        const cache = await this.getCache();
        const requests = await cache.keys();
        return requests
            .map((req) => {
            const url = new URL(req.url);
            return decodeURIComponent(url.pathname.slice(1));
        })
            .filter((key) => key.length > 0);
    }
    async size() {
        const keys = await this.keys();
        return keys.length;
    }
    async prune() {
        const cache = await this.getCache();
        const requests = await cache.keys();
        let removed = 0;
        for (const request of requests) {
            const response = await cache.match(request);
            if (response) {
                try {
                    const data = await response.json();
                    if (data.expiresAt && Date.now() > data.expiresAt) {
                        await cache.delete(request);
                        removed++;
                    }
                }
                catch {
                    await cache.delete(request);
                    removed++;
                }
            }
        }
        return removed;
    }
}
