export function youtube(options) {
    return {
        baseUrl: 'https://www.googleapis.com/youtube/v3',
        headers: {
            'Accept': 'application/json',
        },
        defaults: {
            params: {
                key: options.apiKey
            }
        },
        timeout: 30 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504]
        }
    };
}
