export function linear(options) {
    return {
        baseUrl: 'https://api.linear.app',
        headers: {
            'Authorization': options.apiKey,
            'Content-Type': 'application/json',
        },
        timeout: 30 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 500,
            statusCodes: [408, 429, 500, 502, 503, 504]
        }
    };
}
