export function vercel(options) {
    const params = {};
    if (options.teamId) {
        params.teamId = options.teamId;
    }
    return {
        baseUrl: 'https://api.vercel.com',
        headers: {
            'Authorization': `Bearer ${options.token}`,
            'Content-Type': 'application/json',
        },
        defaults: {
            params,
        },
        timeout: 30 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504]
        }
    };
}
