export function slack(options) {
    return {
        baseUrl: 'https://slack.com/api',
        headers: {
            'Authorization': `Bearer ${options.token}`,
            'Content-Type': 'application/json; charset=utf-8',
        },
        timeout: 30 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504]
        }
    };
}
