export function hubspot(options) {
    return {
        baseUrl: 'https://api.hubapi.com',
        headers: {
            'Authorization': `Bearer ${options.accessToken}`,
            'Content-Type': 'application/json',
        },
        timeout: 30 * 1000,
        retry: {
            maxAttempts: 3,
            backoff: 'exponential',
            delay: 1000,
            statusCodes: [408, 429, 500, 502, 503, 504],
        }
    };
}
export const hubspotContacts = (options) => ({
    ...hubspot(options),
    baseUrl: 'https://api.hubapi.com/crm/v3/objects/contacts',
});
export const hubspotDeals = (options) => ({
    ...hubspot(options),
    baseUrl: 'https://api.hubapi.com/crm/v3/objects/deals',
});
export const hubspotCompanies = (options) => ({
    ...hubspot(options),
    baseUrl: 'https://api.hubapi.com/crm/v3/objects/companies',
});
